using System.Linq.Expressions;using Microsoft.EntityFrameworkCore;using Npgsql;using ZosyalMedya.BuildingBlocks.Application.Persistence;using ZosyalMedya.Modules.Communities.Application.Ports;using ZosyalMedya.Modules.Communities.Domain.Communities;
namespace ZosyalMedya.Modules.Communities.Infrastructure.Persistence;
public sealed class PostgreSqlCommunityRepository(CommunitiesDbContext db):ICommunityRepository{private IQueryable<Community>Full=>db.Communities.Include("_members").Include("_rules").Include("_audit").AsSplitQuery();public async Task<Community?>SelectAsync(Expression<Func<Community,bool>>predicate,CancellationToken cancellationToken=default){var x=await Full.AsNoTracking().Where(predicate).OrderBy(x=>x.Id).Take(2).ToListAsync(cancellationToken);return x.SingleOrDefault();}public async Task<IReadOnlyList<Community>>ListByFilterAsync(Expression<Func<Community,bool>>predicate,QueryOptions<Community>?options=null,CancellationToken cancellationToken=default){options??=new();return await Full.AsNoTracking().Where(predicate).OrderByDescending(x=>x.UpdatedAtUtc).ThenBy(x=>x.Id).Take(options.BoundedLimit).ToListAsync(cancellationToken);}public async Task<CommunityId>CreateAsync(Community entity,CancellationToken cancellationToken=default){try{db.Add(entity);await db.SaveChangesAsync(cancellationToken);db.ChangeTracker.Clear();return entity.Id;}catch(DbUpdateException e)when(e.InnerException is PostgresException{SqlState:PostgresErrorCodes.UniqueViolation}){db.ChangeTracker.Clear();throw new PersistenceConflictException("communities.slug_conflict","Topluluk adresi kullanılıyor.",e);}}public async Task<bool>UpdateAsync(Expression<Func<Community,bool>>predicate,Community replacement,long?expectedVersion=null,CancellationToken cancellationToken=default){var q=Full.Where(predicate);if(expectedVersion.HasValue)q=q.Where(x=>x.Version==expectedVersion);var current=await q.SingleOrDefaultAsync(cancellationToken);if(current is null)return false;db.Entry(current).CurrentValues.SetValues(replacement);Sync(db.Entry(current).Collection("_members"),replacement.Members,x=>x.UserId);Sync(db.Entry(current).Collection("_rules"),replacement.Rules,x=>x.Order);Sync(db.Entry(current).Collection("_audit"),replacement.AuditHistory,x=>x.Sequence);try{return await db.SaveChangesAsync(cancellationToken)>0;}catch(DbUpdateConcurrencyException){return false;}finally{db.ChangeTracker.Clear();}}public async Task<long>DeleteByFilterAsync(Expression<Func<Community,bool>>predicate,CancellationToken cancellationToken=default)=>await db.Communities.Where(predicate).ExecuteDeleteAsync(cancellationToken);private static void Sync<T,TKey>(Microsoft.EntityFrameworkCore.ChangeTracking.CollectionEntry entry,IEnumerable<T>replacement,Func<T,TKey>key)where T:class where TKey:notnull{var current=(ICollection<T>)entry.CurrentValue!;var next=replacement.ToArray();var keys=next.Select(key).ToHashSet();foreach(var stale in current.Where(x=>!keys.Contains(key(x))).ToArray()){current.Remove(stale);entry.EntityEntry.Context.Entry(stale).State=EntityState.Deleted;}foreach(var item in next){var existing=current.SingleOrDefault(x=>EqualityComparer<TKey>.Default.Equals(key(x),key(item)));if(existing is null){current.Add(item);entry.EntityEntry.Context.Entry(item).State=EntityState.Added;}else entry.EntityEntry.Context.Entry(existing).CurrentValues.SetValues(item);}}}
